MOJIBAKE_MARKERS = [
    "鎴",
    "涓",
    "锛",
    "銆",
    "褰",
    "绛",
    "鍦",
    "鐨",
    "灏",
    "宸",
    "泂",
    "汿",
]


def main() -> int:
    issues: list[dict[str, object]] = []
    checked: list[str] = []
    for path in CHECK_PATHS:
        if not path.exists():
            issues.append({"path": str(path), "issue": "missing"})
            continue
        text = path.read_text(encoding="utf-8")
        checked.append(str(path))
        hits = sorted({marker for marker in MOJIBAKE_MARKERS if marker in text})
        if hits:
            issues.append({"path": str(path), "issue": "mojibake_markers", "markers": hits})

    result = {
        "status": "PASS" if not issues else "FAIL",
        "checked_files": checked,
        "issues": issues,
        "boundary": "This is a heuristic manuscript-facing text check; it does not validate scientific claims.",
    }
    print(json.dumps(result, indent=2, ensure_ascii=False))
    return 0 if not issues else 1


if __name__ == "__main__":
    raise SystemExit(main())
